function StepPublish{if(-not $script:Ctx.Paths){throw 'SigningRepository required.'};$p=$script:Ctx.Paths;$s=$script:Ctx.Signing;if(-not $s){$m=ReadMetadata $p.MetadataPath;$s=@{Alias=$m['Keystore Alias'];StorePassword=$m['Store Password'];KeyPassword=$m['Key Password'];KeystorePath=$m['Upload Keystore']}};$project=Join-Path $script:Cfg.Root $script:Cfg.Project;$a=@('publish',$project,'-f',$script:Cfg.Tfm,'-c',$script:Cfg.Config,'-p:AndroidKeyStore=true',"-p:AndroidSigningKeyStore=$($s.KeystorePath)","-p:AndroidSigningKeyAlias=$($s.Alias)","-p:AndroidSigningStorePass=$($s.StorePassword)","-p:AndroidSigningKeyPass=$($s.KeyPassword)",'--no-restore');RunCommand dotnet $a @(9,10);$script:Ctx.Signing=$s;Log 'Android Release publish completed.' Success}
